-- Each person's due-total for a closed period, fixed when it was closed: the dues of their counting claims dated
-- in it. A person with no row here (added after the close) shows 0.00 for it. Cleared when the period reopens.
CREATE TABLE period_person_total (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    period_name VARCHAR(100) NOT NULL,
    person_id BIGINT NOT NULL,
    total DECIMAL(19, 2) NOT NULL,
    PRIMARY KEY (sheet_id, period_name, person_id)
);
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the deferral's body once, publishing its date; refuses (400) a missing or malformed date. */
public class ValidateDeferRequest {
    public void validate(@RequestBody DeferRequest request, Out<Deferral> deferral) throws InvalidClaimException {
        String until = request == null || request.until() == null ? "" : request.until().trim();
        if (until.isEmpty()) {
            throw new InvalidClaimException("Type the date to defer the claim until.");
        }
        try {
            deferral.set(new Deferral(LocalDate.parse(until)));
        } catch (DateTimeParseException ex) {
            throw new InvalidClaimException("Type a date as yyyy-mm-dd.");
        }
    }
}
package net.officefloor.hq.app.claim;

/** What a deferral submits: the date (yyyy-MM-dd) the claim is deferred until (null or blank: none typed). */
public record DeferRequest(String until) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the claim just deferred, with its person's name, then the date it is deferred until. */
public class AuditClaimDeferred {
    public void audit(@Val Claim claim, PersonRepository people, @RequestParam("user") String user, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record("CLAIM_DEFERRED sheet=" + claim.sheetId() + " by=" + user + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().setScale(2).toPlainString()
                + " date=" + claim.date() + Claim.auditNumber(claim.number()) + " until=" + claim.deferredUntil());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Defers the claim until the deferral's date. */
public class DeferClaim {
    public void defer(@Val Claim claim, @Val Deferral deferral, ClaimRepository repository, Out<Claim> deferred) {
        Claim next = claim.deferTo(deferral.until());
        repository.defer(next);
        deferred.set(next);
    }
}
